class Solution { public List<Integer> survivedRobotsHealths(int[] positions,int[] healths,String directions){Integer[] order=new Integer[positions.length];for(int i=0;i<order.length;i++)order[i]=i;Arrays.sort(order,(a,b)->Integer.compare(positions[a],positions[b]));Deque<Integer> stack=new ArrayDeque<>();for(int robot:order){if(directions.charAt(robot)=='R'){stack.addLast(robot);continue;}while(healths[robot]>0&&!stack.isEmpty()){int right=stack.peekLast();if(healths[right]<healths[robot]){healths[right]=0;stack.removeLast();healths[robot]--;}else if(healths[right]==healths[robot]){healths[right]=healths[robot]=0;stack.removeLast();}else{healths[right]--;healths[robot]=0;}}}List<Integer> answer=new ArrayList<>();for(int health:healths)if(health>0)answer.add(health);return answer;} }
